CREATE TABLE akun (id INTEGER PRIMARY KEY, nama TEXT NOT NULL, saldo INTEGER NOT NULL CHECK (saldo >= 0));
CREATE TABLE topup (id INTEGER PRIMARY KEY, akun_id INTEGER NOT NULL REFERENCES akun (id), nominal INTEGER NOT NULL CHECK (nominal > 0));
CREATE TABLE transaksi (id INTEGER PRIMARY KEY, dari INTEGER NOT NULL REFERENCES akun (id), ke INTEGER NOT NULL REFERENCES akun (id), jumlah INTEGER NOT NULL CHECK (jumlah > 0));
-- ADR 6 Tahap 1 (labs/api-t1/schema.sql, diringkas): satu baris koreksi = satu akun, jumlah, alasan
CREATE TABLE koreksi (id INTEGER PRIMARY KEY, akun_id INTEGER NOT NULL REFERENCES akun (id), jumlah INTEGER NOT NULL CHECK (jumlah <> 0), alasan TEXT NOT NULL CHECK (length(trim(alasan)) >= 20));
INSERT INTO akun VALUES (419, 'Budi', 235000), (502, 'Warung Sari', 15000);
INSERT INTO topup (akun_id, nominal) VALUES (419, 250000);
-- Salah bayar sudah terjadi: Budi menekan Bayar ke Warung Sari
INSERT INTO transaksi (dari, ke, jumlah) VALUES (419, 502, 15000);
CREATE VIEW catatan_budi AS
  SELECT 1 AS urut, 'topup' AS catatan, nominal AS jumlah FROM topup WHERE akun_id = 419
  UNION ALL SELECT 2, 'transaksi ke ' || (SELECT nama FROM akun WHERE id = t.ke), -t.jumlah FROM transaksi t WHERE t.dari = 419
  UNION ALL SELECT 3, 'koreksi', jumlah FROM koreksi WHERE akun_id = 419;
CREATE VIEW pertanyaan_pak_hadi AS
  SELECT 1 AS urut, 'baris catatan Budi' AS pertanyaan, (SELECT group_concat(catatan || ' ' || printf('%+d', jumlah), '; ') FROM (SELECT * FROM catatan_budi ORDER BY urut)) AS jawaban_database
  UNION ALL SELECT 2, 'pembayaran yang dikoreksi', coalesce((SELECT 'tidak tersimpan; hanya alasan: ' || alasan FROM koreksi WHERE akun_id = 419), 'belum ada koreksi')
  UNION ALL SELECT 3, 'saldo Budi di app', (SELECT saldo FROM akun WHERE id = 419)
  UNION ALL SELECT 4, 'selisih seluruh sistem (harus 0)', (SELECT sum(saldo) FROM akun) - (SELECT sum(nominal) FROM topup);

