CREATE TABLE buku (id INTEGER PRIMARY KEY, nama TEXT NOT NULL);
CREATE TABLE jurnal (id INTEGER PRIMARY KEY, jenis TEXT NOT NULL, keterangan TEXT NOT NULL, membalik_jurnal_id INTEGER UNIQUE REFERENCES jurnal (id),
  CHECK ((jenis = 'pembalik') = (membalik_jurnal_id IS NOT NULL)),
  CHECK (jenis <> 'pembalik' OR length(trim(keterangan)) >= 20));
CREATE TABLE posting (id INTEGER PRIMARY KEY, jurnal_id INTEGER NOT NULL REFERENCES jurnal (id), buku_id INTEGER NOT NULL REFERENCES buku (id), jumlah INTEGER NOT NULL CHECK (jumlah <> 0));
-- Pagar lab b3-ledger, diringkas: posting pembalik harus cermin jurnal asal.
-- Di PostgreSQL pemeriksaan ini dan jurnal seimbang berjalan saat COMMIT; SQLite memeriksanya per baris.
CREATE TRIGGER pembalik_cermin_asal BEFORE INSERT ON posting
  WHEN (SELECT membalik_jurnal_id FROM jurnal WHERE id = NEW.jurnal_id) IS NOT NULL
   AND NEW.jumlah IS NOT -(SELECT sum(jumlah) FROM posting WHERE buku_id = NEW.buku_id
                            AND jurnal_id = (SELECT membalik_jurnal_id FROM jurnal WHERE id = NEW.jurnal_id))
  BEGIN SELECT RAISE(ABORT, 'pembalik_cermin_asal: posting bukan cermin jurnal asal'); END;
CREATE TRIGGER posting_tidak_diubah BEFORE UPDATE ON posting BEGIN SELECT RAISE(ABORT, 'posting_tidak_diubah'); END;
CREATE TRIGGER posting_tidak_dihapus BEFORE DELETE ON posting BEGIN SELECT RAISE(ABORT, 'posting_tidak_diubah'); END;
INSERT INTO buku VALUES (1, 'tunjangan'), (419, 'Budi'), (502, 'Warung Sari');
INSERT INTO jurnal (id, jenis, keterangan) VALUES (1, 'topup', 'Tunjangan makan Budi'), (2, 'bayar', 'Bayar makan siang di Warung Sari');
-- Salah bayar sudah terjadi: jurnal 2
INSERT INTO posting (jurnal_id, buku_id, jumlah) VALUES (1, 1, -250000), (1, 419, 250000), (2, 419, -15000), (2, 502, 15000);
CREATE VIEW catatan_budi AS
  SELECT p.id AS urut, 'jurnal ' || j.id || ' ' || j.jenis AS catatan, p.jumlah FROM posting p JOIN jurnal j ON j.id = p.jurnal_id WHERE p.buku_id = 419;
CREATE VIEW pertanyaan_pak_hadi AS
  SELECT 1 AS urut, 'baris catatan Budi' AS pertanyaan, (SELECT group_concat(catatan || ' ' || printf('%+d', jumlah), '; ') FROM (SELECT * FROM catatan_budi ORDER BY urut)) AS jawaban_database
  UNION ALL SELECT 2, 'pembayaran yang dikoreksi', coalesce((SELECT 'jurnal ' || a.id || ': ' || a.keterangan FROM jurnal j JOIN jurnal a ON a.id = j.membalik_jurnal_id WHERE j.jenis = 'pembalik'), 'belum ada koreksi')
  UNION ALL SELECT 3, 'saldo Budi di app', (SELECT coalesce(sum(jumlah), 0) FROM posting WHERE buku_id = 419)
  UNION ALL SELECT 4, 'selisih seluruh sistem (harus 0)', (SELECT sum(jumlah) FROM posting);
